export async function createSalesOrder(url: string, key: string, secret: string, data: any) {
  const res = await fetch(`${url}/api/resource/Sales Order`, {
    method: 'POST',
    headers: { 'Authorization': `token ${key}:${secret}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...data, docstatus: 1 })
  });
  return (await res.json()).data;
}

